import 'package:fit_store/features/auth/presentation/screens/on_boarding/on_boarding_screen.dart';import 'package:fit_store/features/auth/presentation/screens/signup/verify_email.dart';import 'package:fit_store/features/auth/presentation/screens/splash_screen/splash_screen.dart';import 'package:fit_store/features/auth/presentation/screens/welcome/welcome_screen.dart';import 'package:fit_store/features/home/domain/entities/categories_entity.dart';import 'package:fit_store/features/home/presentation/screens/home.dart';import 'package:fit_store/features/favourites/presentation/screens/favourite.dart';import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../common/widgets/success_screen/success_screen.dart';import '../features/auth/presentation/screens/forget_password/forget_password_mail/forget_password_mail.dart';import '../features/auth/presentation/screens/forget_password/forget_password_mail/reset_password_screen.dart';import '../features/auth/presentation/screens/login/login_screen.dart';import '../features/auth/presentation/screens/signup/signup_screen.dart';import '../features/cart/presentation/screens/cart.dart';import '../features/checkout/presentation/screens/checkout.dart';import '../features/home/presentation/controller/reviews_cubit/reviews_cubit.dart';import '../features/home/presentation/screens/search/search_screen.dart';import '../features/home/presentation/screens/sub_categories/sub_categories.dart';import '../features/settings/presentation/screens/address/user_address.dart';import '../features/settings/presentation/screens/address/widgets/add_new_address.dart';import '../features/settings/presentation/screens/order/order.dart';import '../features/settings/presentation/screens/profile/profile_screen.dart';import '../features/store/domain/entities/brand_entity.dart';import '../features/store/presentation/screens/all_brands/all_brands.dart';import '../features/store/presentation/screens/all_brands/brand_products.dart';import '../features/store/presentation/screens/store.dart';import '../features/home/domain/entities/product_entity.dart';import '../features/home/presentation/screens/product_detail/product_detail.dart';import '../features/home/presentation/screens/product_reviews/product_reviews.dart';import '../navigation_menu.dart';class AppRoutes {  static Route<dynamic> onGenerateRoute(RouteSettings settings) {    switch (settings.name) {      case SplashScreen.routeName:        return MaterialPageRoute(          builder: (_) => const SplashScreen(),          settings: settings,        );      case WelcomeScreen.routeName:        return MaterialPageRoute(          builder: (_) => const WelcomeScreen(),          settings: settings,        );      case SignupScreen.routeName:        return MaterialPageRoute(          builder: (_) =>   SignupScreen(),          settings: settings,        );      case VerifyEmailScreen.routeName:        final email = settings.arguments as String;        return MaterialPageRoute(          builder: (_) => VerifyEmailScreen(            email: email,          ),          settings: settings,        );      case ResetPasswordScreen.routeName:        final email = settings.arguments as String;        return MaterialPageRoute(          builder: (_) => ResetPasswordScreen(            email: email,          ),          settings: settings,        );      case SuccessScreen.routeName:        final args = settings.arguments as Map<String, dynamic>? ?? {};        return MaterialPageRoute(          builder: (_) => SuccessScreen(            image: args['image'] as String,            title: args['title'] as String,            subTitle: args['subTitle'] as String,            onPressed: args['onPressed'] as void Function(BuildContext),          ),          settings: settings,        );      case OnBoardingScreen.routeName:        return MaterialPageRoute(          builder: (_) => const OnBoardingScreen(),          settings: settings,        );      case NavigationMenu.routeName:        return MaterialPageRoute(          builder: (_) =>   NavigationMenu(),          settings: settings,        );      case LoginScreen.routeName:        return MaterialPageRoute(          builder: (_) => const LoginScreen(),          settings: settings,        );      case HomeScreen.routeName:        return MaterialPageRoute(          builder: (_) => const HomeScreen(),          settings: settings,        );      case SearchScreen.routeName:        return MaterialPageRoute(          builder: (_) => const SearchScreen(),          settings: settings,        );      case StoreScreen.routeName:        return MaterialPageRoute(          builder: (_) => const StoreScreen(),          settings: settings,        );      case ProductDetailScreen.routeName:        final product = settings.arguments as ProductEntity;        return MaterialPageRoute(          builder: (_) => ProductDetailScreen(product: product,),          settings: settings,        );      case BrandProducts.routeName:        final brand = settings.arguments as BrandEntity;        return MaterialPageRoute(          builder: (_) => BrandProducts(brand: brand,),          settings: settings,        );      case ProfileScreen.routeName:        return MaterialPageRoute(          builder: (_) => const ProfileScreen(),          settings: settings,        );      case CartScreen.routeName:        return MaterialPageRoute(          builder: (_) => const CartScreen(),          settings: settings,        );      case CheckoutScreen.routeName:        return MaterialPageRoute(          builder: (_) => const CheckoutScreen(),          settings: settings,        );      case FavouriteScreen.routeName:        return MaterialPageRoute(          builder: (_) => const FavouriteScreen(),          settings: settings,        );      case ProductReviewsScreen.routeName:        final args = settings.arguments as Map<String, dynamic>;        final productId = args['productId'] as String;        final reviewsCubit = args['cubit'] as ReviewsCubit;        return MaterialPageRoute(          builder: (_) => BlocProvider.value(            value: reviewsCubit,            child: ProductReviewsScreen(productId: productId),          ),          settings: settings,        );      case AddNewAddressScreen.routeName:        return MaterialPageRoute(          builder: (_) => const AddNewAddressScreen(),          settings: settings,        );      case UserAddressScreen.routeName:        return MaterialPageRoute(          builder: (_) => const UserAddressScreen(),          settings: settings,        );      case SubCategoriesScreen.routeName:        final category = settings.arguments as CategoryEntity;        return MaterialPageRoute(          builder: (_) => SubCategoriesScreen(category: category,),          settings: settings,        );      case AllBrandsScreen.routeName:        return MaterialPageRoute(          builder: (_) => const AllBrandsScreen(),          settings: settings,        );      case ForgetPasswordMailScreen.routeName:        return MaterialPageRoute(          builder: (_) => const ForgetPasswordMailScreen(),          settings: settings,        );      case OrderScreen.routeName:        return MaterialPageRoute(          builder: (_) => const OrderScreen(),          settings: settings,        );      default:        return MaterialPageRoute(          builder: (_) => const Scaffold(),          settings: settings,        );    }  }}